require 'Foraging/forageSystem'

local function category(name, zoneChance)
    local def = forageSystem.catDefs[name]
    if def ~= nil then def.zoneChance = zoneChance end
end

local function item(itemType, zones)
    local def = forageSystem.itemDefs[itemType]
    if def ~= nil then def.zones = zones end
end

